<?php
namespace Avanik;
defined('ABSPATH') || exit;
final class TicketingService {
 public static function issue(string $booking_id): array|\WP_Error { $booking=BookingRepository::find_by_id($booking_id); if(!$booking)return new \WP_Error('avanik_booking_not_found','Booking پیدا نشد.'); if(($booking['status']??'')!==Booking::STATUS_CONFIRMED)return new \WP_Error('avanik_booking_not_confirmed','Booking هنوز تأیید Provider نشده است.'); $provider_key=sanitize_key($booking['provider']??$booking['provider_key']??''); $manager=apply_filters('avanik_provider_manager',null); if(!$manager instanceof ProviderManager)return new \WP_Error('avanik_provider_manager_missing','Provider Manager در دسترس نیست.'); $provider=$manager->get($provider_key); if(!$provider)return new \WP_Error('avanik_provider_unavailable','Provider در دسترس نیست.'); $result=apply_filters('avanik_ticket_issue',$provider->issue_ticket($booking),$booking,$provider); if(empty($result['success']))return new \WP_Error('avanik_ticket_issue_failed',$result['message']??'صدور بلیت ناموفق بود.'); BookingLifecycle::transition($booking_id,Booking::STATUS_TICKETED,['pnr'=>sanitize_text_field($result['pnr']??''),'ticket_number'=>sanitize_text_field($result['ticket_number']??''),'voucher_reference'=>sanitize_text_field($result['voucher_reference']??''),'issued_at'=>current_time('mysql')]); do_action('avanik_ticket_issued',$booking_id,$result); return $result; }
}